'use strict';
function draftWritingSupport(draft){editorItem=draft;editorField=null;installEditorCompanion(draft,{dates:false});}
function writingDestination(body=document.querySelector('.modal-body')){const fields=[...body.querySelectorAll('textarea,input,[contenteditable=true]')].filter(el=>isWritingField(el)&&el.getClientRects().length);return fields.includes(editorField)?editorField:fields.find(el=>el.isContentEditable||el.tagName==='TEXTAREA')||fields.find(el=>!el.classList.contains('editor-title'))||fields[0];}
function installSnippetButton(item,body){const button=document.createElement('button');button.className='secondary mode-assist';button.id='editor-snippets';button.innerHTML='<i data-lucide="blocks"></i> Snippet Shelf';button.onclick=()=>snippetPicker(item,body);body.append(button);}
function snippetPicker(item,body){const field=writingDestination(body);if(!field){toast('Choose an editable writing field first.');return;}const original=field.isContentEditable?field.innerHTML:field.value,start=field.selectionStart,end=field.selectionEnd,selection=window.getSelection(),range=field.isContentEditable&&selection.rangeCount&&field.contains(selection.anchorNode)&&field.contains(selection.focusNode)?selection.getRangeAt(0).cloneRange():null;const modal=body.closest('.modal');modal.inert=true;const layer=document.createElement('div');layer.className='choice-overlay';layer.innerHTML='<section class="choice-box snippet-picker" role="dialog" aria-modal="true" aria-labelledby="snippet-picker-title"><h2 id="snippet-picker-title">Snippet Shelf</h2><p class="hint">Tap a block to insert its text into the writing field you were using.</p><input id="snippet-picker-search" type="search" aria-label="Find a reusable snippet" placeholder="Search snippets or tags…"><div id="snippet-picker-results" class="reference-list"></div><p id="snippet-picker-error" role="status"></p><button data-choice-cancel class="secondary">Back to writing</button></section>';document.body.append(layer);const close=()=>{modal.inert=false;layer.remove();field.focus({preventScroll:true});};$('[data-choice-cancel]',layer).onclick=close;const entries=state.items.filter(n=>!n.deletedAt&&n.snippets&&!NotaThinking.capsuleClosed(n)).flatMap(n=>n.snippets.entries.filter(e=>e.text.trim()).map(e=>({...e,shelf:n.title})));
 const render=()=>{const q=$('#snippet-picker-search',layer).value.toLowerCase();$('#snippet-picker-results',layer).innerHTML=entries.filter(e=>[e.title,e.tags,e.text,e.shelf].join(' ').toLowerCase().includes(q)).map((e,i)=>`<button data-paste-snippet="${esc(e.id)}"><strong>${esc(e.title||'Untitled snippet')}</strong><small>${esc(e.shelf)} · ${esc(e.text.slice(0,130))}</small></button>`).join('')||'<p class="hint">No reusable text yet. Create a Snippet Shelf from Desk, add a block, then return here.</p>';$$('[data-paste-snippet]',layer).forEach(b=>b.onclick=()=>{const e=entries.find(e=>e.id===b.dataset.pasteSnippet),now=field.isContentEditable?field.innerHTML:field.value;if(now!==original){$('#snippet-picker-error',layer).textContent='This writing changed. Return to it and open Snippet Shelf again.';return;}const value=field.isContentEditable?plain(field.innerHTML):field.value,max=field.maxLength>0?field.maxLength:100000,selected=Number.isInteger(start)?end-start:range&&!range.collapsed?range.toString().length:0;if(value.length-selected+e.text.length+1>max){$('#snippet-picker-error',layer).textContent='This block is too long for the selected writing field.';return;}close();if(field.isContentEditable){field.focus();const sel=window.getSelection();sel.removeAllRanges();const r=range||document.createRange();if(!range){r.selectNodeContents(field);r.collapse(false);}sel.addRange(r);document.execCommand('insertText',false,e.text);}else{field.setRangeText(e.text,Number.isInteger(start)?start:field.value.length,Number.isInteger(end)?end:field.value.length,'end');}field.dispatchEvent(new Event('input',{bubbles:true}));activeEditor?.();touch(item);toast('Snippet inserted in this item.');});};$('#snippet-picker-search',layer).oninput=render;layer.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}if(e.key==='Tab'){const f=$$('button,input',layer).filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}});render();$('#snippet-picker-search',layer).focus();}
function insertSnippetIntoNote(entry,source){modal('Insert a reusable block',`<label class="field">Note<select id="snippet-note-target"><option value="">Choose a note…</option>${state.items.filter(n=>!n.deletedAt&&!NotaThinking.capsuleClosed(n)&&n.type==='note'&&!n.inputMode).map(n=>`<option value="${n.id}">${esc(n.title)} · ${esc(state.workspaces.find(w=>w.id===n.workspace)?.name||'Canvas')}</option>`).join('')}<option value="__new__">Create a new note</option></select></label><p class="hint">For a structured editor, open it and use its Snippet Shelf button to insert into a specific field.</p>`,`<button id="snippet-target-back" class="secondary">Back to shelf</button><button id="snippet-target-insert" class="primary">Insert snippet</button>`);$('#snippet-target-back').onclick=()=>editItem(source);$('#snippet-target-insert').onclick=()=>{let n=state.items.find(n=>n.id===$('#snippet-note-target').value);if($('#snippet-note-target').value==='__new__')n=addItem('note',{workspace:source.workspace,title:entry.title||'A reusable thought'});if(!n)return;if(plain(n.html||'').length+entry.text.length>100000){toast('This note is full. Choose another note.');return;}NotaCore.rememberVersion(n);n.html=(n.html||'')+entry.text.split('\n').map(line=>'<p>'+esc(line)+'</p>').join('');touch(n);restoreWindow(n);editItem(n);toast('Snippet inserted in this note.');};}
function installDateMemory(item,body){let timer;const panel=document.createElement('section');panel.className='date-memory';panel.hidden=true;panel.setAttribute('aria-label','Dates in your writing');const title=body.querySelector('.editor-title');if(title)title.after(panel);else body.append(panel);
 const refresh=()=>{if(!body.isConnected||!body.getClientRects().length)return;const fields=[...body.querySelectorAll('textarea,input,[contenteditable=true]')].filter(el=>!panel.contains(el)&&isWritingField(el)&&el.getClientRects().length),writing=fields.map(el=>el.isContentEditable?plain(el.innerHTML):el.value).join('\n'),suggestions=NotaDates.detect(writing,{year:item.calendar?Number(item.calendar.month.slice(0,4)):new Date().getFullYear()});panel.hidden=!suggestions.length;if(!suggestions.length)return;const calendars=state.items.filter(n=>!n.deletedAt&&n.calendar&&!NotaThinking.capsuleClosed(n)),previous=panel.querySelector('select')?.value||calendars.find(n=>n.workspace===item.workspace)?.id||'';
 panel.innerHTML=`<h3><i data-lucide="calendar-plus"></i> Dates in your writing</h3><p class="hint">Choose Remember to add a calendar entry and mark its date. Yearless dates use ${item.calendar?item.calendar.month.slice(0,4):new Date().getFullYear()}.</p>${item.calendar?'':`<label>Calendar<select data-date-calendar><option value="">Create a calendar on this canvas</option>${calendars.map(n=>`<option value="${n.id}" ${n.id===previous?'selected':''}>${esc(n.title)}</option>`).join('')}</select></label>`}<div class="date-memory-list"></div>`;
 const list=panel.querySelector('.date-memory-list');for(const candidate of suggestions){let hash=2166136261;for(const char of candidate.key)hash=Math.imul(hash^char.charCodeAt(0),16777619);const key=candidate.date+'-'+(hash>>>0).toString(36),remembered=calendars.find(n=>n.calendar.events.some(e=>e.sourceItemId===item.id&&e.sourceKey===key)),button=document.createElement('button');button.className='secondary';button.textContent=(remembered?'Open remembered date: ':'Remember ')+new Date(candidate.date+'T12:00:00').toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})+' · '+candidate.title;button.onclick=()=>{if(remembered){remembered.calendar.selected=candidate.date;remembered.calendar.month=candidate.date.slice(0,7);restoreWindow(remembered);editItem(remembered);return;}activeEditor?.();let target=item.calendar?item:calendars.find(n=>n.id===panel.querySelector('[data-date-calendar]').value);if(!target){const cal=NotaPlanning.calendar(candidate.date);cal.month=candidate.date.slice(0,7);cal.selected=candidate.date;cal.cardView='month';target=addItem('note',{workspace:item.workspace,title:'Dates to remember',inputMode:'calendar',calendar:cal,tag:'Calendar'});}if(target.calendar.events.length>=300){toast('This calendar is full. Choose another calendar.');return;}target.calendar.events.push({id:uid(),date:candidate.date,time:'',title:candidate.title,body:candidate.body,sourceItemId:item.id,sourceKey:key});target.calendar.month=candidate.date.slice(0,7);target.calendar.selected=candidate.date;target.html=NotaPlanning.calendarHTML(target.calendar);touch(target);renderBoard();refresh();toast('Remembered in '+target.title+'.');};list.append(button);}icons();};body.addEventListener('input',e=>{if(panel.contains(e.target))return;clearTimeout(timer);timer=setTimeout(refresh,450);});setTimeout(refresh,50);}
